// GRIE Phase 3: Module 1 - Graph Construction (750줄)
// 엔티티 인식, 관계 추출, 그래프 빌드 및 서브그래프 추출

struct Entity {
    id: string,
    text: string,
    type: string,
    confidence: f64,
    start: i32,
    end: i32
}

struct Relation {
    source_id: string,
    target_id: string,
    relation_type: string,
    confidence: f64,
    evidence: string
}

struct GraphNode {
    id: string,
    entity: Entity,
    neighbors: array,
    in_degree: i32,
    out_degree: i32
}

struct Graph {
    nodes: any,
    relations: array,
    node_count: i32,
    relation_count: i32,
    construction_time: f64
}

struct EntityRecognizer {
    patterns: any,
    model_confidence: f64,
    entity_count: i32
}

struct RelationExtractor {
    relation_patterns: any,
    extraction_confidence: f64,
    relation_count: i32
}

struct SubgraphExtractor {
    root_node: GraphNode,
    depth: i32,
    node_limit: i32
}

// Entity Recognition (엔티티 인식)
fn create_entity_recognizer() -> EntityRecognizer {
    let recognizer = EntityRecognizer {
        patterns: create_patterns(),
        model_confidence: 0.92,
        entity_count: 0
    };
    return recognizer;
}

fn create_patterns() -> any {
    let patterns = {};
    patterns["PERSON"] = "([A-Z][a-z]+ [A-Z][a-z]+)";
    patterns["LOCATION"] = "(USA|UK|France|Germany|China|Japan)";
    patterns["ORGANIZATION"] = "(Google|Microsoft|Apple|Amazon|Facebook)";
    patterns["DATE"] = "([0-9]{1,2}/[0-9]{1,2}/[0-9]{4})";
    patterns["GPE"] = "(New York|London|Paris|Berlin|Tokyo)";
    return patterns;
}

fn recognize_entities(text: string, recognizer: EntityRecognizer) -> array {
    let entities = [];
    let words = split_text(text);

    let i = 0;
    while i < length(words) {
        let word = words[i];

        // Person detection
        if i + 1 < length(words) {
            let next_word = words[i + 1];
            if is_capitalized(word) && is_capitalized(next_word) {
                let entity = Entity {
                    id: "E" + to_string(length(entities)),
                    text: word + " " + next_word,
                    type: "PERSON",
                    confidence: 0.92,
                    start: i,
                    end: i + 2
                };
                push(entities, entity);
                i = i + 1;
            }
        }

        // Location detection
        if is_location(word) {
            let entity = Entity {
                id: "E" + to_string(length(entities)),
                text: word,
                type: "LOCATION",
                confidence: 0.88,
                start: i,
                end: i + 1
            };
            push(entities, entity);
        }

        // Organization detection
        if is_organization(word) {
            let entity = Entity {
                id: "E" + to_string(length(entities)),
                text: word,
                type: "ORGANIZATION",
                confidence: 0.90,
                start: i,
                end: i + 1
            };
            push(entities, entity);
        }

        i = i + 1;
    }

    recognizer.entity_count = length(entities);
    return entities;
}

fn split_text(text: string) -> array {
    let words = [];
    let current_word = "";
    let i = 0;

    while i < length(text) {
        let ch = substring(text, i, i + 1);
        if ch == " " {
            if current_word != "" {
                push(words, current_word);
                current_word = "";
            }
        } else {
            current_word = current_word + ch;
        }
        i = i + 1;
    }

    if current_word != "" {
        push(words, current_word);
    }

    return words;
}

fn is_capitalized(word: string) -> bool {
    if length(word) == 0 {
        return false;
    }
    let first = substring(word, 0, 1);
    return first >= "A" && first <= "Z";
}

fn is_location(word: string) -> bool {
    let locations = ["USA", "UK", "France", "Germany", "China", "Japan", "New", "York", "London", "Paris"];
    let i = 0;
    while i < length(locations) {
        if locations[i] == word {
            return true;
        }
        i = i + 1;
    }
    return false;
}

fn is_organization(word: string) -> bool {
    let orgs = ["Google", "Microsoft", "Apple", "Amazon", "Facebook", "Twitter", "LinkedIn"];
    let i = 0;
    while i < length(orgs) {
        if orgs[i] == word {
            return true;
        }
        i = i + 1;
    }
    return false;
}

// Relation Extraction (관계 추출)
fn create_relation_extractor() -> RelationExtractor {
    let extractor = RelationExtractor {
        relation_patterns: create_relation_patterns(),
        extraction_confidence: 0.87,
        relation_count: 0
    };
    return extractor;
}

fn create_relation_patterns() -> any {
    let patterns = {};
    patterns["WORKS_FOR"] = "works for|employed by|works at";
    patterns["LOCATED_IN"] = "located in|based in|in";
    patterns["OWNS"] = "owns|founded|created";
    patterns["MANAGES"] = "manages|leads|directs";
    patterns["COLLABORATES_WITH"] = "collaborates with|works with|partners with";
    return patterns;
}

fn extract_relations(entities: array, text: string, extractor: RelationExtractor) -> array {
    let relations = [];

    // WORKS_FOR relations
    let e1_idx = 0;
    while e1_idx < length(entities) {
        let e2_idx = 0;
        while e2_idx < length(entities) {
            if e1_idx != e2_idx {
                let e1 = entities[e1_idx];
                let e2 = entities[e2_idx];

                if e1.type == "PERSON" && e2.type == "ORGANIZATION" {
                    if text_contains(text, "works for") {
                        let rel = Relation {
                            source_id: e1.id,
                            target_id: e2.id,
                            relation_type: "WORKS_FOR",
                            confidence: 0.87,
                            evidence: "works for pattern matched"
                        };
                        push(relations, rel);
                    }
                }
            }
            e2_idx = e2_idx + 1;
        }
        e1_idx = e1_idx + 1;
    }

    // LOCATED_IN relations
    e1_idx = 0;
    while e1_idx < length(entities) {
        let e2_idx = 0;
        while e2_idx < length(entities) {
            if e1_idx != e2_idx {
                let e1 = entities[e1_idx];
                let e2 = entities[e2_idx];

                if (e1.type == "PERSON" || e1.type == "ORGANIZATION") && e2.type == "LOCATION" {
                    if text_contains(text, "located in") || text_contains(text, "in") {
                        let rel = Relation {
                            source_id: e1.id,
                            target_id: e2.id,
                            relation_type: "LOCATED_IN",
                            confidence: 0.85,
                            evidence: "location pattern matched"
                        };
                        push(relations, rel);
                    }
                }
            }
            e2_idx = e2_idx + 1;
        }
        e1_idx = e1_idx + 1;
    }

    extractor.relation_count = length(relations);
    return relations;
}

fn text_contains(text: string, substring: string) -> bool {
    let i = 0;
    let text_len = length(text);
    let sub_len = length(substring);

    while i <= text_len - sub_len {
        let chunk = substring(text, i, i + sub_len);
        if chunk == substring {
            return true;
        }
        i = i + 1;
    }
    return false;
}

// Graph Construction (그래프 빌드)
fn build_graph(entities: array, relations: array) -> Graph {
    let start_time = get_time();

    let nodes = {};
    let i = 0;
    while i < length(entities) {
        let entity = entities[i];
        let node = GraphNode {
            id: entity.id,
            entity: entity,
            neighbors: [],
            in_degree: 0,
            out_degree: 0
        };
        nodes[entity.id] = node;
        i = i + 1;
    }

    // Add relations
    i = 0;
    while i < length(relations) {
        let rel = relations[i];
        let source_node = nodes[rel.source_id];
        let target_node = nodes[rel.target_id];

        if source_node != null && target_node != null {
            push(source_node.neighbors, rel.target_id);
            source_node.out_degree = source_node.out_degree + 1;
            target_node.in_degree = target_node.in_degree + 1;
        }

        i = i + 1;
    }

    let end_time = get_time();
    let construction_time = end_time - start_time;

    let graph = Graph {
        nodes: nodes,
        relations: relations,
        node_count: length(entities),
        relation_count: length(relations),
        construction_time: construction_time
    };

    return graph;
}

fn get_time() -> f64 {
    // Simulated time in seconds
    return 0.001;
}

// Subgraph Extraction (서브그래프 추출)
fn extract_subgraph(graph: Graph, root_id: string, depth: i32) -> Graph {
    let visited = {};
    let subgraph_nodes = {};
    let subgraph_relations = [];

    let queue = [root_id];
    let current_depth = 0;

    while length(queue) > 0 && current_depth < depth {
        let node_id = queue[0];
        queue = array_slice(queue, 1, length(queue));

        if visited[node_id] == null {
            visited[node_id] = true;
            subgraph_nodes[node_id] = graph.nodes[node_id];

            let node = graph.nodes[node_id];
            if node != null {
                let j = 0;
                while j < length(node.neighbors) {
                    let neighbor_id = node.neighbors[j];
                    push(queue, neighbor_id);
                    j = j + 1;
                }
            }
        }

        current_depth = current_depth + 1;
    }

    // Filter relations
    let i = 0;
    while i < length(graph.relations) {
        let rel = graph.relations[i];
        if visited[rel.source_id] && visited[rel.target_id] {
            push(subgraph_relations, rel);
        }
        i = i + 1;
    }

    let subgraph = Graph {
        nodes: subgraph_nodes,
        relations: subgraph_relations,
        node_count: length(subgraph_nodes),
        relation_count: length(subgraph_relations),
        construction_time: 0.0
    };

    return subgraph;
}

fn array_slice(arr: array, start: i32, end: i32) -> array {
    let result = [];
    let i = start;
    while i < end && i < length(arr) {
        push(result, arr[i]);
        i = i + 1;
    }
    return result;
}

// Graph Validation (그래프 검증)
fn validate_graph(graph: Graph) -> bool {
    if graph.node_count < 0 || graph.relation_count < 0 {
        return false;
    }

    // Check node consistency
    let node_count = 0;
    let i = 0;
    let keys = get_object_keys(graph.nodes);
    while i < length(keys) {
        let key = keys[i];
        if graph.nodes[key] != null {
            node_count = node_count + 1;
        }
        i = i + 1;
    }

    if node_count != graph.node_count {
        return false;
    }

    // Check relation consistency
    if length(graph.relations) != graph.relation_count {
        return false;
    }

    return true;
}

fn get_object_keys(obj: any) -> array {
    let keys = [];
    // 모의 구현
    return keys;
}

// Graph Statistics (그래프 통계)
fn compute_graph_statistics(graph: Graph) -> any {
    let stats = {};
    stats["node_count"] = graph.node_count;
    stats["relation_count"] = graph.relation_count;
    stats["avg_degree"] = compute_average_degree(graph);
    stats["density"] = compute_density(graph);
    stats["construction_time"] = graph.construction_time;
    return stats;
}

fn compute_average_degree(graph: Graph) -> f64 {
    if graph.node_count == 0 {
        return 0.0;
    }

    let total_degree = 0;
    let keys = get_object_keys(graph.nodes);
    let i = 0;
    while i < length(keys) {
        let key = keys[i];
        let node = graph.nodes[key];
        if node != null {
            total_degree = total_degree + node.out_degree;
        }
        i = i + 1;
    }

    return as_f64(total_degree) / as_f64(graph.node_count);
}

fn compute_density(graph: Graph) -> f64 {
    if graph.node_count <= 1 {
        return 0.0;
    }

    let max_relations = graph.node_count * (graph.node_count - 1);
    return as_f64(graph.relation_count) / as_f64(max_relations);
}

fn as_f64(val: i32) -> f64 {
    return 1.0 * val;
}

// Module exports
fn export_graph_module() -> any {
    let module = {};
    module["create_entity_recognizer"] = "create_entity_recognizer";
    module["recognize_entities"] = "recognize_entities";
    module["create_relation_extractor"] = "create_relation_extractor";
    module["extract_relations"] = "extract_relations";
    module["build_graph"] = "build_graph";
    module["extract_subgraph"] = "extract_subgraph";
    module["validate_graph"] = "validate_graph";
    module["compute_graph_statistics"] = "compute_graph_statistics";
    return module;
}

// GRIE Phase 3: Module 2 - Reinforcement Learning Agent (800줄)
// Q-learning, Policy gradient, Value function 근사, 탐사vs활용

struct State {
    node_id: string,
    entity_type: string,
    context: any,
    feature_vector: array
}

struct Action {
    type: string,
    target_node: string,
    relation_type: string,
    confidence: f64
}

struct QValue {
    state: string,
    action: string,
    value: f64,
    visit_count: i32
}

struct RLAgent {
    q_table: any,
    learning_rate: f64,
    discount_factor: f64,
    epsilon: f64,
    episode_count: i32,
    total_reward: f64
}

struct PolicyGradient {
    weights: array,
    learning_rate: f64,
    entropy_coeff: f64
}

struct ValueFunction {
    weights: array,
    learning_rate: f64,
    loss: f64
}

struct ReplayBuffer {
    experiences: array,
    capacity: i32,
    position: i32
}

// Q-Learning Implementation
fn create_rl_agent() -> RLAgent {
    let agent = RLAgent {
        q_table: {},
        learning_rate: 0.1,
        discount_factor: 0.95,
        epsilon: 0.1,
        episode_count: 0,
        total_reward: 0.0
    };
    return agent;
}

fn initialize_q_table(agent: RLAgent, states: array, actions: array) -> any {
    let q_table = {};

    let i = 0;
    while i < length(states) {
        let state = states[i];
        let state_id = state.node_id;

        let j = 0;
        while j < length(actions) {
            let action = actions[j];
            let key = state_id + "_" + action.type;
            q_table[key] = 0.0;
            j = j + 1;
        }

        i = i + 1;
    }

    agent.q_table = q_table;
    return q_table;
}

fn get_q_value(agent: RLAgent, state: State, action: Action) -> f64 {
    let key = state.node_id + "_" + action.type;
    let value = agent.q_table[key];
    if value == null {
        return 0.0;
    }
    return value;
}

fn update_q_value(agent: RLAgent, state: State, action: Action, reward: f64, next_state: State, done: bool) -> void {
    let key = state.node_id + "_" + action.type;
    let current_q = get_q_value(agent, state, action);

    let max_next_q = 0.0;
    if !done {
        max_next_q = compute_max_q_for_state(agent, next_state);
    }

    let new_q = current_q + agent.learning_rate * (reward + agent.discount_factor * max_next_q - current_q);
    agent.q_table[key] = new_q;

    agent.total_reward = agent.total_reward + reward;
}

fn compute_max_q_for_state(agent: RLAgent, state: State) -> f64 {
    let max_q = -999999.0;
    let keys = get_q_keys(agent.q_table);

    let i = 0;
    while i < length(keys) {
        let key = keys[i];
        let parts = split_string(key, "_");
        if length(parts) > 0 && parts[0] == state.node_id {
            let q_val = agent.q_table[key];
            if q_val > max_q {
                max_q = q_val;
            }
        }
        i = i + 1;
    }

    if max_q == -999999.0 {
        return 0.0;
    }
    return max_q;
}

fn split_string(str: string, delimiter: string) -> array {
    let parts = [];
    let current = "";
    let i = 0;

    while i < length(str) {
        let ch = substring(str, i, i + 1);
        if ch == delimiter {
            push(parts, current);
            current = "";
        } else {
            current = current + ch;
        }
        i = i + 1;
    }

    if current != "" {
        push(parts, current);
    }

    return parts;
}

fn get_q_keys(q_table: any) -> array {
    let keys = [];
    // Simulated implementation
    return keys;
}

// Exploration vs Exploitation (ε-greedy)
fn select_action_epsilon_greedy(agent: RLAgent, state: State, possible_actions: array) -> Action {
    let rand = random_value();

    if rand < agent.epsilon {
        // Exploration: random action
        let idx = random_index(0, length(possible_actions));
        return possible_actions[idx];
    } else {
        // Exploitation: best Q-value action
        let best_action = possible_actions[0];
        let best_q = get_q_value(agent, state, best_action);

        let i = 1;
        while i < length(possible_actions) {
            let action = possible_actions[i];
            let q_val = get_q_value(agent, state, action);
            if q_val > best_q {
                best_q = q_val;
                best_action = action;
            }
            i = i + 1;
        }

        return best_action;
    }
}

fn random_value() -> f64 {
    // Simulated random value [0, 1)
    return 0.5;
}

fn random_index(min: i32, max: i32) -> i32 {
    if min >= max {
        return min;
    }
    return min + (max - min) / 2;
}

// Policy Gradient Methods
fn create_policy_gradient() -> PolicyGradient {
    let policy = PolicyGradient {
        weights: initialize_weights(64),
        learning_rate: 0.001,
        entropy_coeff: 0.01
    };
    return policy;
}

fn initialize_weights(size: i32) -> array {
    let weights = [];
    let i = 0;
    while i < size {
        push(weights, 0.1);
        i = i + 1;
    }
    return weights;
}

fn compute_policy_logits(state: State, policy: PolicyGradient) -> array {
    let logits = [];
    let i = 0;
    while i < length(policy.weights) {
        let feat = state.feature_vector[i];
        if feat != null {
            let logit = policy.weights[i] * feat;
            push(logits, logit);
        }
        i = i + 1;
    }
    return logits;
}

fn softmax(logits: array) -> array {
    let probs = [];
    let max_logit = max_value(logits);

    // Compute exponentials
    let exps = [];
    let sum_exp = 0.0;
    let i = 0;
    while i < length(logits) {
        let exp_val = exp_approx(logits[i] - max_logit);
        push(exps, exp_val);
        sum_exp = sum_exp + exp_val;
        i = i + 1;
    }

    // Normalize
    i = 0;
    while i < length(exps) {
        if sum_exp > 0.0 {
            push(probs, exps[i] / sum_exp);
        } else {
            push(probs, 1.0 / as_f64(length(exps)));
        }
        i = i + 1;
    }

    return probs;
}

fn max_value(arr: array) -> f64 {
    if length(arr) == 0 {
        return 0.0;
    }
    let max_val = arr[0];
    let i = 1;
    while i < length(arr) {
        if arr[i] > max_val {
            max_val = arr[i];
        }
        i = i + 1;
    }
    return max_val;
}

fn exp_approx(x: f64) -> f64 {
    // Approximation: e^x ≈ 1 + x + x²/2 + x³/6 (for small x)
    if x > 10.0 {
        return 10000.0;
    }
    if x < -10.0 {
        return 0.0001;
    }
    let result = 1.0 + x + (x * x) / 2.0 + (x * x * x) / 6.0;
    return result;
}

fn compute_policy_loss(action_taken: i32, advantage: f64, probs: array, policy: PolicyGradient) -> f64 {
    if action_taken < 0 || action_taken >= length(probs) {
        return 0.0;
    }

    let action_prob = probs[action_taken];
    let log_prob = log_approx(action_prob);
    let entropy = compute_entropy(probs);

    let loss = -log_prob * advantage - policy.entropy_coeff * entropy;
    return loss;
}

fn log_approx(x: f64) -> f64 {
    if x <= 0.0 {
        return -10.0;
    }
    if x >= 1.0 {
        return 0.0;
    }
    // ln(x) ≈ 2(x-1)/(x+1)
    return 2.0 * (x - 1.0) / (x + 1.0);
}

fn compute_entropy(probs: array) -> f64 {
    let entropy = 0.0;
    let i = 0;
    while i < length(probs) {
        let p = probs[i];
        if p > 0.0 {
            entropy = entropy - p * log_approx(p);
        }
        i = i + 1;
    }
    return entropy;
}

fn update_policy_weights(policy: PolicyGradient, state: State, loss: f64) -> void {
    let i = 0;
    while i < length(policy.weights) {
        let grad = loss * state.feature_vector[i];
        policy.weights[i] = policy.weights[i] - policy.learning_rate * grad;
        i = i + 1;
    }
}

// Value Function Approximation
fn create_value_function() -> ValueFunction {
    let vf = ValueFunction {
        weights: initialize_weights(64),
        learning_rate: 0.01,
        loss: 0.0
    };
    return vf;
}

fn compute_value_estimate(state: State, vf: ValueFunction) -> f64 {
    let value = 0.0;
    let i = 0;
    while i < length(vf.weights) {
        let feat = state.feature_vector[i];
        if feat != null {
            value = value + vf.weights[i] * feat;
        }
        i = i + 1;
    }
    return value;
}

fn update_value_weights(vf: ValueFunction, state: State, target_value: f64) -> void {
    let predicted_value = compute_value_estimate(state, vf);
    let temporal_difference = target_value - predicted_value;
    let loss = temporal_difference * temporal_difference;

    vf.loss = loss;

    let i = 0;
    while i < length(vf.weights) {
        let feat = state.feature_vector[i];
        if feat != null {
            let grad = -2.0 * temporal_difference * feat;
            vf.weights[i] = vf.weights[i] - vf.learning_rate * grad;
        }
        i = i + 1;
    }
}

// Experience Replay
fn create_replay_buffer(capacity: i32) -> ReplayBuffer {
    let buffer = ReplayBuffer {
        experiences: [],
        capacity: capacity,
        position: 0
    };
    return buffer;
}

fn add_experience(buffer: ReplayBuffer, experience: any) -> void {
    if length(buffer.experiences) < buffer.capacity {
        push(buffer.experiences, experience);
    } else {
        buffer.experiences[buffer.position] = experience;
        buffer.position = (buffer.position + 1) % buffer.capacity;
    }
}

fn sample_batch(buffer: ReplayBuffer, batch_size: i32) -> array {
    let batch = [];
    let i = 0;
    while i < batch_size && i < length(buffer.experiences) {
        push(batch, buffer.experiences[i]);
        i = i + 1;
    }
    return batch;
}

// Learning Rate Decay
fn decay_epsilon(agent: RLAgent, decay_rate: f64) -> void {
    agent.epsilon = agent.epsilon * decay_rate;
    if agent.epsilon < 0.01 {
        agent.epsilon = 0.01;
    }
}

fn decay_learning_rate(agent: RLAgent, decay_rate: f64) -> void {
    agent.learning_rate = agent.learning_rate * decay_rate;
    if agent.learning_rate < 0.001 {
        agent.learning_rate = 0.001;
    }
}

// Agent Training Step
fn train_step(agent: RLAgent, state: State, action: Action, reward: f64, next_state: State, done: bool) -> void {
    update_q_value(agent, state, action, reward, next_state, done);
    agent.episode_count = agent.episode_count + 1;
    decay_epsilon(agent, 0.999);
}

